    post_api_sales_spoken_copy: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    model: string;
                    productName: string;
                    /** @description 当前商品原始资料，不含生成的概括、买点或文案。 */
                    facts?: string;
                    /** @description 待优化稿，不构成事实证据。 */
                    sourceCopy?: string;
                    /** @default false */
                    reviewOnly?: boolean;
                    /** @enum {string} */
                    voiceMode: "speech" | "voiceover";
                    duration: number;
                    targetCps?: number;
                    beats: {
                        index: number;
                        start: number;
                        end: number;
                        action: string;
                        expression?: string;
                        transition?: string;
                        spokenLine?: string;
                        subtitle?: string;
                    }[];
                };
            };
        };
        responses: {
            /** @description 改写稿或原稿已通过本次语义验收 */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        success: true;
                        model: string;
                        /** @description 本次写稿规则版本；reviewOnly 未执行写稿时为空。 */
                        promptVersion: string;
                        reviewPromptVersion: string;
                        beats: {
                            index: number;
                            spokenLine: string;
                            subtitle: string;
                        }[];
                    };
                };
            };
            /** @description 手工原稿未通过基础或语义验收，保留原稿并返回具体问题。 */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description 审稿失败、回执无效或三稿仍未通过，不返回成功稿与审核版本。临时审稿故障可携带 pendingReview，供下次 reviewOnly 原字续验；候选稿不表示审核通过。 */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        success: false;
                        error: string;
                        code?: string;
                        stage?: string;
                        pendingReview?: {
                            promptVersion: string;
                            beats: {
                                index: number;
                                spokenLine: string;
                                subtitle: string;
                            }[];
                        };
                    };
                };
            };
        };
    };
